        await sut.DeleteAsync(projectId, requirement.Id, CancellationToken.None);

        await using var db = factory.CreateDbContext();
        Assert.Empty(db.SubmissionRequirements);
    }

    [Fact]
    public async Task GetAsync_MissingRequirement_ReturnsNotFound()
    {
        var factory = new TestSubmissionDbContextFactory();
        var projectId = Guid.NewGuid();
        var studentId = Guid.NewGuid();
        var sut = CreateSut(factory, AuthorizedContext(projectId, studentId), Substitute.For<IUserProfileClient>());

        var exception = await Assert.ThrowsAsync<ApiException>(() => sut.GetAsync(
            projectId, Guid.NewGuid(), CancellationToken.None));

        Assert.Equal(404, exception.StatusCode);
    }

    private static SubmissionRequirementService CreateSut(
        TestSubmissionDbContextFactory factory,
        IProjectAuthorizationClient auth,
        IUserProfileClient profile) => new(
            factory,
            auth,
            profile,
            new SubmissionOptions { AllowedFileTypes = ["pdf", "docx", "pptx", "zip"] },
            new StorageOptions { MaximumFileSizeBytes = 10 * 1024 * 1024 },
            new FixedTimeProvider(Now));

    private static IProjectAuthorizationClient AuthorizedContext(Guid projectId, Guid studentId)
    {
        var auth = Substitute.For<IProjectAuthorizationClient>();
        auth.GetSubmissionContextAsync(projectId, Arg.Any<CancellationToken>()).Returns(
            new ProjectSubmissionContext(
                new ProjectStudentContext(studentId, "Sam Student", "sam@example.edu", "IT001"),
                [new ProjectStudentContext(studentId, "Sam Student", "sam@example.edu", "IT001")]));
        return auth;
    }

    private static async Task<SubmissionRequirement> SeedRequirementAsync(
        TestSubmissionDbContextFactory factory,
        Guid projectId,
        Guid studentId,
        string status)
    {
        var requirement = new SubmissionRequirement
        {
            Id = Guid.NewGuid(),
            ProjectId = projectId,
            Title = "Final report",
            AllowedFileTypes = "pdf,docx",
            MaxFileSizeBytes = 10 * 1024 * 1024,
            Status = status,
            ResponsibilityMode = SubmissionConstants.ResponsibilityMode.ProjectLeader,
            AssignedStudentId = studentId,
            AssignedStudentName = "Sam Student",
            CreatedBy = Guid.NewGuid(),
            CreatedByName = "Ada Supervisor",
            CreatedAt = Now
        };
        await using var db = factory.CreateDbContext();
        db.SubmissionRequirements.Add(requirement);
        await db.SaveChangesAsync(CancellationToken.None);
        return requirement;
    }

    private sealed class TestSubmissionDbContextFactory : IDbContextFactory<SubmissionDbContext>
    {
        private readonly DbContextOptions<SubmissionDbContext> _options =
            new DbContextOptionsBuilder<SubmissionDbContext>()
                .UseInMemoryDatabase($"submission-requirements-{Guid.NewGuid():N}")
                .Options;
        public SubmissionDbContext CreateDbContext() => new(_options);
        public Task<SubmissionDbContext> CreateDbContextAsync(CancellationToken cancellationToken = default) =>
            Task.FromResult(CreateDbContext());
    }

    private sealed class FixedTimeProvider(DateTimeOffset now) : TimeProvider
    {
        public override DateTimeOffset GetUtcNow() => now;
    }
}

using ResearchTrack.SubmissionService.Features;

namespace ResearchTrack.SubmissionService.MutationTests;

public sealed class SubmissionFileRulesBoundaryTests
{
    [Theory]
    [InlineData(" .PDF ", "pdf")]
    [InlineData("..DOCX", "docx")]
    [InlineData("zip", "zip")]
    public void NormalizeExtension_StripsDotsWhitespaceAndNormalizesCase(string input, string expected)
    {
        Assert.Equal(expected, SubmissionFileRules.NormalizeExtension(input));
    }

    [Theory]
    [InlineData("README")]
    [InlineData("file.")]
    public void ExtensionFromFileName_ReturnsNullWhenUsableExtensionIsMissing(string fileName)
    {
        Assert.Null(SubmissionFileRules.ExtensionFromFileName(fileName));
    }

    [Theory]
    [InlineData("pdf", "application/pdf")]
    [InlineData("DOCX", "application/vnd.openxmlformats-officedocument.wordprocessingml.document")]
    [InlineData("pptx", "application/vnd.openxmlformats-officedocument.presentationml.presentation")]
    [InlineData("zip", "application/zip")]
    public void CanonicalContentType_ReturnsExpectedMimeType(string extension, string expected)
    {
        Assert.Equal(expected, SubmissionFileRules.CanonicalContentType(extension));
    }

    [Fact]
    public void CanonicalContentType_ReturnsNullForUnknownExtension()
    {
        Assert.Null(SubmissionFileRules.CanonicalContentType("exe"));
    }

    [Theory]
    [InlineData("pdf", " APPLICATION/PDF ")]
    [InlineData("ZIP", " application/x-zip-compressed ")]
    public void ContentTypeMatchesExtension_NormalizesContentTypeAndExtension(string extension, string contentType)
    {
        Assert.True(SubmissionFileRules.ContentTypeMatchesExtension(extension, contentType));
    }

    [Theory]
    [InlineData("pdf", "application/octet-stream")]
    [InlineData("exe", "application/octet-stream")]
    [InlineData("docx", "application/pdf")]
    public void ContentTypeMatchesExtension_RejectsUnknownOrMismatchedPairs(string extension, string contentType)
    {
        Assert.False(SubmissionFileRules.ContentTypeMatchesExtension(extension, contentType));
    }

    [Fact]
    public void ParseAllowedTypes_RemovesEmptyDuplicatesAndSortsDeterministically()
    {
        Assert.Equal(
            ["docx", "pdf", "zip"],
            SubmissionFileRules.ParseAllowedTypes(" .PDF,docx,pdf, ,ZIP "));
    }

    [Fact]
    public void SerializeAllowedTypes_RemovesEmptyDuplicatesAndSortsDeterministically()
    {
        Assert.Equal(
            "docx,pdf,zip",
            SubmissionFileRules.SerializeAllowedTypes(["ZIP", "", ".pdf", "docx", "PDF"]));
    }

    [Fact]
    public void SafeOriginalFileName_StripsPathAndHonorsExactLengthBoundary()
    {
        Assert.Equal("report.pdf", SubmissionFileRules.SafeOriginalFileName(" /tmp/report.pdf ", 20));
        Assert.Equal("12345", SubmissionFileRules.SafeOriginalFileName("12345", 5));
        Assert.Equal("12345", SubmissionFileRules.SafeOriginalFileName("123456789", 5));
    }
}

